import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { expect, test } from '@playwright/test';

// Generated by: cargo run --release -p bi-fixtures -- oracle --rows 1000000
// Values come from the independent Rust fixture oracle, never the queries API.
const oracle: {
  seed: string;
  rows: string;
  totals: { row_count: string; amount: { sum: string | null } };
  by_region: { region: string | null; row_count: string; amount_sum: string | null }[];
} = JSON.parse(
  readFileSync(fileURLToPath(new URL('./sales.oracle.json', import.meta.url)), 'utf8'),
);
const display = (value: string | null) => {
  if (value === null) return 'Sin dato';
  const [whole, fraction] = value.split('.');
  return (
    whole!.replace(/\B(?=(\d{3})+(?!\d))/g, '.') + (fraction === undefined ? '' : ',' + fraction)
  );
};

test('real 1M-row stack: exact totals, region filter, NULL and lazy chart navigation', async ({
  page,
  request,
}) => {
  test.setTimeout(150_000);
  expect(oracle.seed).toBe('42');
  expect(oracle.rows).toBe('1000000');
  await expect
    .poll(async () => (await request.get('/health/ready')).status(), { timeout: 120_000 })
    .toBe(200);
  const errors: string[] = [];
  page.on('pageerror', (error) => errors.push(error.message));
  const assets: string[] = [];
  page.on('request', (r) => {
    if (r.url().endsWith('.js')) assets.push(r.url());
  });
  // Support the stacked #13 branch and the final authenticated contract from #12.
  const me = await request.get('/api/v1/session');
  if (me.status() === 401) {
    await page.goto('/login');
    await page.getByRole('button', { name: 'Entrar' }).click();
    await expect(page).toHaveURL('/');
  } else await page.goto('/');
  await page.getByRole('link', { name: 'Estado del sistema', exact: true }).click();
  await expect(
    page.getByRole('heading', { name: 'Estado del sistema', exact: true }),
  ).toBeVisible();
  const before = new Set(assets);
  await page.getByRole('link', { name: 'Exploración', exact: true }).click();
  await expect(page.getByTestId('kpi-count')).toHaveText(display(oracle.totals.row_count));
  await expect(page.getByTestId('kpi-amount')).toHaveText(display(oracle.totals.amount.sum));
  for (const row of oracle.by_region) {
    const tr = page.getByRole('row').filter({
      has: page.getByRole('rowheader', { name: row.region ?? 'Sin región', exact: true }),
    });
    await expect(tr.getByRole('cell').nth(0)).toHaveText(display(row.row_count));
    await expect(tr.getByRole('cell').nth(1)).toHaveText(display(row.amount_sum));
  }
  await expect(page.getByRole('img').locator('svg')).toBeVisible();
  // Identify the chart chunk by its registered series code and verify it was
  // downloaded only after entering exploration (including hover preloading).
  const chartAssets = [];
  for (const url of new Set(assets)) {
    if ((await (await request.get(url)).text()).includes('Importe relativo')) chartAssets.push(url);
  }
  expect(chartAssets).toHaveLength(1);
  expect(before.has(chartAssets[0]!)).toBe(false);
  for (const region of ['north', 'east', null]) {
    const expected = oracle.by_region.find((row) => row.region === region)!;
    await page.getByLabel('Región', { exact: true }).selectOption(region ?? 'null');
    await expect(page.getByTestId('kpi-count')).toHaveText(display(expected.row_count));
    await expect(page.getByTestId('kpi-amount')).toHaveText(display(expected.amount_sum));
    await expect(page.getByRole('row')).toHaveCount(2);
    await expect(page.getByRole('rowheader')).toHaveText(region ?? 'Sin región');
    await expect(page.getByRole('img').locator('svg')).toBeVisible();
  }
  await page.getByRole('link', { name: 'Inicio', exact: true }).click();
  await expect(page.getByRole('img')).toHaveCount(0);
  await page.getByRole('link', { name: 'Exploración', exact: true }).click();
  await expect(page.getByTestId('kpi-amount')).toHaveText(display(oracle.totals.amount.sum));
  await expect(page.getByRole('img').locator('svg')).toBeVisible();
  // Change the outgoing request only; the real Rust API produces the Problem.
  await page.route('**/api/v1/queries', async (route) => {
    const query = route.request().postDataJSON();
    await route.continue({ postData: JSON.stringify({ ...query, dataset: 'unknown_dataset' }) });
  });
  await page.getByRole('button', { name: 'Actualizar resultados' }).click();
  await expect(page.getByRole('alert')).toContainText('invalid_query');
  await expect(page.getByRole('alert')).toContainText('HTTP 422');
  await expect(page.getByRole('alert')).toContainText('Solicitud:');
  await expect(page.getByTestId('kpi-count')).toHaveCount(0);
  await page.unroute('**/api/v1/queries');
  await page.getByRole('button', { name: 'Reintentar' }).click();
  await expect(page.getByTestId('kpi-amount')).toHaveText(display(oracle.totals.amount.sum));
  // A nonexistent region is a valid filter with genuinely empty server data.
  await page.getByLabel('Región', { exact: true }).evaluate((select) => {
    const option = document.createElement('option');
    option.value = 'absent-region';
    option.textContent = 'Región sin ventas';
    select.appendChild(option);
  });
  await page.getByLabel('Región', { exact: true }).selectOption('absent-region');
  await expect(page.getByTestId('kpi-count')).toHaveText('0');
  await expect(page.getByTestId('kpi-amount')).toHaveText('Sin dato');
  await expect(page.getByRole('status')).toHaveText('No hay ventas para este filtro.');
  await expect(page.getByRole('table')).toHaveCount(0);
  if (me.status() === 401) {
    const logout = await page.request.post('/api/v1/logout', {
      headers: { Origin: new URL(page.url()).origin },
    });
    expect(logout.status()).toBe(204);
    await page.getByRole('button', { name: 'Actualizar resultados' }).click();
    await expect(page).toHaveURL('/login');
  }
  expect(errors).toEqual([]);
});
